-- READ-ONLY exact-key and nearest 300-second target check for legacy rows in existing gap windows.
SELECT o.gap_id, COUNT(*) AS old_source_rows, SUM(w.`dateTime` IS NOT NULL) AS exact_wh1080_matches, SUM(z.`dateTime` IS NOT NULL) AS exact_eu_old_matches, SUM(r.`dateTime` IS NOT NULL) AS exact_reconstruction_matches, SUM(MOD(o.`dateTime`,300)=0) AS on_300s_grid, SUM(MOD(o.`dateTime`,300)<>0) AS off_300s_grid, COUNT(DISTINCT (o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0))) AS distinct_nearest_300s_slots, COUNT(*)-COUNT(DISTINCT (o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0))) AS source_projection_collisions, SUM(rp.`dateTime` IS NOT NULL) AS rows_projecting_to_occupied_reconstruction_slots, SUM(NOT (o.`outTemp` <=> w.`outTemp`)) AS outTemp_old_wh_conflicts, SUM(NOT (o.`outTemp` <=> z.`outTemp`)) AS outTemp_old_euold_conflicts, SUM(NOT (o.`outHumidity` <=> w.`outHumidity`)) AS outHumidity_old_wh_conflicts, SUM(NOT (o.`outHumidity` <=> z.`outHumidity`)) AS outHumidity_old_euold_conflicts, SUM(NOT (o.`rain` <=> w.`rain`)) AS rain_old_wh_conflicts, SUM(NOT (o.`rain` <=> z.`rain`)) AS rain_old_euold_conflicts, SUM(NOT (o.`rainRate` <=> w.`rainRate`)) AS rainRate_old_wh_conflicts, SUM(NOT (o.`rainRate` <=> z.`rainRate`)) AS rainRate_old_euold_conflicts, SUM(NOT (o.`windSpeed` <=> w.`windSpeed`)) AS windSpeed_old_wh_conflicts, SUM(NOT (o.`windSpeed` <=> z.`windSpeed`)) AS windSpeed_old_euold_conflicts, SUM(NOT (o.`windGust` <=> w.`windGust`)) AS windGust_old_wh_conflicts, SUM(NOT (o.`windGust` <=> z.`windGust`)) AS windGust_old_euold_conflicts, SUM(NOT (o.`windDir` <=> w.`windDir`)) AS windDir_old_wh_conflicts, SUM(NOT (o.`windDir` <=> z.`windDir`)) AS windDir_old_euold_conflicts, SUM(NOT (o.`barometer` <=> w.`barometer`)) AS barometer_old_wh_conflicts, SUM(NOT (o.`barometer` <=> z.`barometer`)) AS barometer_old_euold_conflicts, SUM(NOT (o.`pressure` <=> w.`pressure`)) AS pressure_old_wh_conflicts, SUM(NOT (o.`pressure` <=> z.`pressure`)) AS pressure_old_euold_conflicts, SUM(NOT (o.`altimeter` <=> w.`altimeter`)) AS altimeter_old_wh_conflicts, SUM(NOT (o.`altimeter` <=> z.`altimeter`)) AS altimeter_old_euold_conflicts, SUM(o.`usUnits`<>w.`usUnits`) AS usUnits_old_wh_conflicts, SUM(o.`interval`<>w.`interval`) AS interval_old_wh_conflicts, SUM(o.`usUnits`<>z.`usUnits`) AS usUnits_old_euold_conflicts, SUM(o.`interval`<>z.`interval`) AS interval_old_euold_conflicts FROM (SELECT CASE WHEN `dateTime`>1264189800 AND `dateTime`<1264196700 THEN 1 WHEN `dateTime`>1265658600 AND `dateTime`<1265665500 THEN 2 WHEN `dateTime`>1267117500 AND `dateTime`<1267126200 THEN 3 WHEN `dateTime`>1267133100 AND `dateTime`<1267140300 THEN 4 WHEN `dateTime`>1268089500 AND `dateTime`<1268096100 THEN 5 WHEN `dateTime`>1268590500 AND `dateTime`<1268599500 THEN 6 WHEN `dateTime`>1269203100 AND `dateTime`<1269221700 THEN 7 WHEN `dateTime`>1271607600 AND `dateTime`<1271614800 THEN 8 WHEN `dateTime`>1275230100 AND `dateTime`<1275237600 THEN 9 WHEN `dateTime`>1275593400 AND `dateTime`<1275605700 THEN 10 WHEN `dateTime`>1276377900 AND `dateTime`<1276397100 THEN 11 WHEN `dateTime`>1276794900 AND `dateTime`<1276801500 THEN 12 WHEN `dateTime`>1277986500 AND `dateTime`<1277997900 THEN 13 WHEN `dateTime`>1278514500 AND `dateTime`<1278541500 THEN 14 WHEN `dateTime`>1278852300 AND `dateTime`<1278864000 THEN 15 WHEN `dateTime`>1280078100 AND `dateTime`<1280085000 THEN 16 WHEN `dateTime`>1280091000 AND `dateTime`<1280099100 THEN 17 WHEN `dateTime`>1281032100 AND `dateTime`<1281043800 THEN 18 WHEN `dateTime`>1281292200 AND `dateTime`<1281307800 THEN 19 WHEN `dateTime`>1281742800 AND `dateTime`<1281752700 THEN 20 WHEN `dateTime`>1281785400 AND `dateTime`<1281792900 THEN 21 WHEN `dateTime`>1281981600 AND `dateTime`<1281987900 THEN 22 WHEN `dateTime`>1285695600 AND `dateTime`<1285716900 THEN 23 WHEN `dateTime`>1286637600 AND `dateTime`<1286642700 THEN 24 WHEN `dateTime`>1287438600 AND `dateTime`<1287453600 THEN 25 WHEN `dateTime`>1288218600 AND `dateTime`<1288225500 THEN 26 WHEN `dateTime`>1289602500 AND `dateTime`<1289609100 THEN 27 WHEN `dateTime`>1292068800 AND `dateTime`<1292075700 THEN 28 ELSE NULL END AS gap_id, `dateTime`, `outTemp`, `outHumidity`, `rain`, `rainRate`, `windSpeed`, `windGust`, `windDir`, `barometer`, `pressure`, `altimeter`, `usUnits`, `interval` FROM `old_weewx`.`archive` WHERE (`dateTime`>1264189800 AND `dateTime`<1264196700) OR (`dateTime`>1265658600 AND `dateTime`<1265665500) OR (`dateTime`>1267117500 AND `dateTime`<1267126200) OR (`dateTime`>1267133100 AND `dateTime`<1267140300) OR (`dateTime`>1268089500 AND `dateTime`<1268096100) OR (`dateTime`>1268590500 AND `dateTime`<1268599500) OR (`dateTime`>1269203100 AND `dateTime`<1269221700) OR (`dateTime`>1271607600 AND `dateTime`<1271614800) OR (`dateTime`>1275230100 AND `dateTime`<1275237600) OR (`dateTime`>1275593400 AND `dateTime`<1275605700) OR (`dateTime`>1276377900 AND `dateTime`<1276397100) OR (`dateTime`>1276794900 AND `dateTime`<1276801500) OR (`dateTime`>1277986500 AND `dateTime`<1277997900) OR (`dateTime`>1278514500 AND `dateTime`<1278541500) OR (`dateTime`>1278852300 AND `dateTime`<1278864000) OR (`dateTime`>1280078100 AND `dateTime`<1280085000) OR (`dateTime`>1280091000 AND `dateTime`<1280099100) OR (`dateTime`>1281032100 AND `dateTime`<1281043800) OR (`dateTime`>1281292200 AND `dateTime`<1281307800) OR (`dateTime`>1281742800 AND `dateTime`<1281752700) OR (`dateTime`>1281785400 AND `dateTime`<1281792900) OR (`dateTime`>1281981600 AND `dateTime`<1281987900) OR (`dateTime`>1285695600 AND `dateTime`<1285716900) OR (`dateTime`>1286637600 AND `dateTime`<1286642700) OR (`dateTime`>1287438600 AND `dateTime`<1287453600) OR (`dateTime`>1288218600 AND `dateTime`<1288225500) OR (`dateTime`>1289602500 AND `dateTime`<1289609100) OR (`dateTime`>1292068800 AND `dateTime`<1292075700)) o LEFT JOIN `weewx_WH1080`.`archive` w ON w.`dateTime`=o.`dateTime` LEFT JOIN `pocasi-loucka.eu_old`.`archive` z ON z.`dateTime`=o.`dateTime` LEFT JOIN `loucka_reconstruction`.`archive` r ON r.`dateTime`=o.`dateTime` LEFT JOIN `loucka_reconstruction`.`archive` rp ON rp.`dateTime`=(o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0)) WHERE o.gap_id IS NOT NULL GROUP BY o.gap_id ORDER BY o.gap_id;
